 9→  --tui-background-accent-1-hover: #{gt.$primary-dark};
10→  --tui-background-accent-1-pressed: #{gt.$primary-darker};
11→  --tui-background-accent-2: #{gt.$accent-orange};
12→  --tui-background-accent-2-hover: #{gt.$accent-orange-light};
13→  --tui-background-accent-2-pressed: #{gt.$accent-orange};
14→  --tui-background-elevation-1: #{gt.$neutral-white};
15→  --tui-background-elevation-2: #{gt.$neutral-white};
16→
17→  // Text
18→  --tui-text-primary: #{gt.$primary-darker};
19→  --tui-text-secondary: #{gt.$primary-dark};
20→  --tui-text-tertiary: #{gt.$neutral-mid};
