76→  --gt-neutral-mid: #{gt.$neutral-mid};
77→  --gt-text: #{gt.$neutral-white};
78→  --gt-text-secondary: #{gt.$neutral-mid};
79→  --gt-surface: #{gt.$primary-dark};
