 1→import { TestBed } from '@angular/core/testing';
 2→import { signal, WritableSignal } from '@angular/core';
 3→import { TUI_DARK_MODE } from '@taiga-ui/core';
 4→import { AppComponent } from '../app';
 5→import { appConfig } from '../app.config';
 6→
 7→describe('Theme Integration', () => {
 8→  let darkModeSignal: WritableSignal<boolean>;
 9→
10→  beforeEach(async () => {
11→    darkModeSignal = signal(false);
12→
13→    await TestBed.configureTestingModule({
14→      imports: [AppComponent],
15→      providers: [
16→        ...appConfig.providers,
17→        { provide: TUI_DARK_MODE, useValue: darkModeSignal },
18→      ],
19→    }).compileComponents();
20→  });
21→
22→  it('should set tuiTheme attribute on tui-root based on dark mode signal', () => {
23→    const fixture = TestBed.createComponent(AppComponent);
24→    fixture.detectChanges();
25→
26→    const tuiRoot = fixture.nativeElement.querySelector('tui-root');
27→    expect(tuiRoot.getAttribute('tuiTheme')).toBe('light');
28→  });
29→
30→  it('should switch tuiTheme to dark when dark mode signal is true', () => {
31→    darkModeSignal.set(true);
32→    const fixture = TestBed.createComponent(AppComponent);
33→    fixture.detectChanges();
34→
35→    const tuiRoot = fixture.nativeElement.querySelector('tui-root');
36→    expect(tuiRoot.getAttribute('tuiTheme')).toBe('dark');
37→  });
38→});
